import { Component, createEffect, createMemo, createSignal, For, onCleanup, onMount, Show } from "solid-js";

import { InputEngineEvent, InputEngineEventName } from "#core/ui/input/input-support.js";
import LensManager, {
	LensLayerDisabledEventName,
	LensLayerEnabledEventName,
	LensLayerEvent,
} from "#core/ui/lenses/lens-manager.js";
import { ComponentID } from "#core/ui/utilities/utilities-component-id.js";
import { Icon as IconUtils } from "#core/ui/utilities/utilities-image.js";
import { AudioContextProvider } from "#core/ui-next/components/audio-context-provider.jsx";
import { CloseButton } from "#core/ui-next/components/close-button.jsx";
import { FiligreeTitle } from "#core/ui-next/components/filigree-title.jsx";
import { defineLegacyComponent } from "#core/ui-next/components/fxs-solid-component.js";
import { Hotkeys } from "#core/ui-next/components/hotkeys.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { KBMNavHelp } from "#core/ui-next/components/nav-help.jsx";
import { useAudio } from "#core/ui-next/services/audio-support.js";
import { IsControllerActive, IsKeyboardActive, IsMouseActive, IsTouchActive } from "#core/ui-next/services/input.js";
import { ComponentUtilities } from "#core/ui-next/utilities/component-utilities.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

import { UnitMapDecorationSupport } from "#base/ui/interface-modes/support-unit-map-decoration.js";
import { HideMiniMapEvent } from "#base/ui/mini-map/panel-mini-map.js";
import { TicketSection } from "#base/ui-next/tooltips/plot-tooltip/components/utility.jsx";

import styles from "#base/ui/settler-legend/panel-settler-legend.scss?url";
//-------------------------------------------------------------
//#region Constants
// Ideally we move this data somewhere else
// So it's shared between the layer and lens.
//-------------------------------------------------------------
const SETTLEMENT_DATA: { description: string; class: string; color?: string }[] = [
	{
		description: "LOC_UI_SETTLER_LEGEND_BAD",
		class: "settler-legend-hex",
		color: "rgb(105, 9, 9)",
	},
	{
		description: "LOC_UI_SETTLER_LEGEND_OKAY",
		class: "settler-legend-hex",
		color: "rgb(180, 158, 40)",
	},
	{
		description: "LOC_UI_SETTLER_LEGEND_GOOD",
		class: "settler-legend-hex",
		color: "rgb(40, 238, 190)",
	},
	{
		description: "LOC_UI_SETTLER_LEGEND_FLOOD_RISK",
		class: "settler-legend-flood",
	},
	{
		description: "LOC_UI_SETTLER_LEGEND_ERUPTION_RISK",
		class: "settler-legend-volcano",
	},
	{
		description: "LOC_UI_SETTLER_LEGEND_RECOMMENDED",
		class: "settler-legend-city-recommend",
	},
];
//-------------------------------------------------------------
//#region Main Panel
//-------------------------------------------------------------
const SettlerLegendPanel: Component = () => {
	const [showDetails, setShowDetails] = createSignal<boolean>(LensManager.isLayerEnabled("fxs-radial-measure-layer"));
	const isUnit = createMemo(() => ComponentID.isValid(UI.Player.getHeadSelectedUnit()));
	const isKBM = createMemo(() => IsKeyboardActive() || IsMouseActive());
	const isSmallScreen = useIsSmallScreen();
	const navHelp = () => {
		const icon = IconUtils.getIconFromActionName("unit-skip-turn");

		if (icon != "ICON_KEY_SPACE") {
			return (
				<KBMNavHelp
					actionName="unit-skip-turn"
					class="mx-2 size-12"
				/>
			);
		} else {
			return <div class="size-12 bg-contain bg-no-repeat img-pc_icon_space mx-2" />;
		}
	};

	onMount(() => {
		window.addEventListener(InputEngineEventName, handleWindowEngineInput);
		window.addEventListener(LensLayerEnabledEventName, handleLensChange);
		window.addEventListener(LensLayerDisabledEventName, handleLensChange);
	});

	onCleanup(() => {
		window.removeEventListener(InputEngineEventName, handleWindowEngineInput);
		window.removeEventListener(LensLayerEnabledEventName, handleLensChange);
		window.removeEventListener(LensLayerDisabledEventName, handleLensChange);
	});

	const triggerRadialToggle = () => {
		LensManager.toggleLayer("fxs-radial-measure-layer");
		useAudio("AppealLens")(showDetails() ? "open" : "close");
	};

	const handleLensChange = (event: LensLayerEvent) => {
		if (event.detail.layer === "fxs-radial-measure-layer") {
			setShowDetails(LensManager.isLayerEnabled("fxs-radial-measure-layer"));
		}
	};

	const handleWindowEngineInput = (inputEvent: InputEngineEvent) => {
		if (inputEvent.detail.status == InputActionStatuses.FINISH) {
			if (inputEvent.isCancelInput() || inputEvent.detail.name == "keyboard-escape") {
				LensManager.disableLayer("fxs-radial-measure-layer");
				if (isUnit()) return;
				LensManager.setActiveLens("fxs-default-lens");

				inputEvent.preventDefault();
				inputEvent.stopImmediatePropagation();
				return;
			}

			switch (inputEvent.detail.name) {
				case "shell-action-1":
				case "notification":
				case "swap-plot-selection":
				case "touch-tap":
				case "unit-skip-turn":
					triggerRadialToggle();

					inputEvent.preventDefault();
					inputEvent.stopImmediatePropagation();
					return;
			}
		}
	};

	createEffect(() => {
		if (isSmallScreen()) {
			window.dispatchEvent(new HideMiniMapEvent(true));
		} else {
			window.dispatchEvent(new HideMiniMapEvent(false));
		}
	});

	createEffect(() => {
		if (IsControllerActive()) {
			Input.setActiveContext(InputContext.Unit);
			if (showDetails()) {
				window.dispatchEvent(new CustomEvent("ui-hide-plot-vfx", { bubbles: false }));
			} else {
				window.dispatchEvent(new CustomEvent("ui-show-plot-vfx", { bubbles: false }));
			}
		} else {
			Input.setActiveContext(InputContext.World);
		}
	});

	return (
		<div class="absolute h-screen">
			<div
				id="panel-settler-legend"
				class={"relative flex-col py-2 pointer-events-auto img-tooltip-bg fxs-subsystem-frame pt-4 mt-3"}
			>
				<div class="inset-0 absolute frame-box" />
				{/* This is just here for the Nav Tray */}
				<Hotkeys
					hotkeys={[
						{
							hotkeyAction: "shell-action-1",
							navTrayText: showDetails()
								? "LOC_UI_SETTLER_LEGEND_HIDE_RULER"
								: "LOC_UI_SETTLER_LEGEND_SHOW_RULER",
							onActivate: triggerRadialToggle,
						},
					]}
				/>
				<div class="relative flex flex-col px-6 w-96 items-stretch max-h-full">
					<FiligreeTitle.H3
						class="mb-1 flex items-center"
						textClass="text-base"
						text="LOC_UI_SETTLER_LEGEND_HEADER"
					/>
					<TicketSection class="flex-auto min-h-0 flex flex-col py-4 gap-1">
						<For each={SETTLEMENT_DATA}>
							{(item) => (
								<div class="flex flex-row items-center relative min-h-16">
									<div
										class={`absolute ${item.class} bg-contain bg-no-repeat`}
										classList={{
											"size-16": item.class == "settler-legend-hex",
											"size-12": item.class !== "settler-legend-hex",
											"m-2": item.class !== "settler-legend-hex",
										}}
										style={item.color ? { "fxs-background-image-tint": item.color } : {}}
									/>
									<L10n.Stylize
										class="font-body text-sm ml-16"
										text={item.description}
									/>
								</div>
							)}
						</For>
					</TicketSection>
					<AudioContextProvider segment="AppealLens">
						<Show
							fallback={<div class="size-2" />}
							when={!IsControllerActive()}
						>
							<div class="flex flex-row justify-center items-center">
								<Show when={IsTouchActive()}>
									<Icon
										class="size-8 m-3"
										name={`url("blp:handpointer")`}
										isUrl={true}
									/>
								</Show>
								<Show when={isKBM()}>{navHelp()}</Show>
								<L10n.Stylize
									text={
										showDetails()
											? "LOC_UI_SETTLER_LEGEND_HIDE_RULER"
											: "LOC_UI_SETTLER_LEGEND_SHOW_RULER"
									}
									class="text-sm font-body uppercase mr-2"
									style={{
										"letter-spacing": "-0.5px",
									}}
									role="heading"
								/>
							</div>
						</Show>
					</AudioContextProvider>
				</div>
				<CloseButton
					class={`${IsControllerActive() ? "hidden" : ""} absolute right-1 top-1`}
					onActivate={() => {
						if (isUnit()) {
							UI.Player.deselectAllUnits();
							UnitMapDecorationSupport.manager.deactivate();
						}

						LensManager.setActiveLens("fxs-default-lens");
					}}
					hotkeyAction="cancel"
					navTrayText="LOC_GENERIC_BACK"
				/>
			</div>
		</div>
	);
};
//#endregion

defineLegacyComponent("panel-settler-legend", { classNames: ["absolute"] }, (_attrs, _element) => {
	return <SettlerLegendPanel />;
});
ComponentUtilities.loadStyles(styles);
